 private static final Map<String,JSONObject> INDEX=new LinkedHashMap<>();
 private Xmm2025SaveConditionPreviewEngine(){}
 static {try{for(String raw:RAW){JSONObject row=new JSONObject(raw);String key=key(row.optString("id"),row.optString("action"));if(INDEX.put(key,row)!=null)throw new IllegalStateException("duplicate save condition profile");}if(INDEX.size()!=PROFILE_COUNT)throw new IllegalStateException("save condition profile count");}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 private static String key(String monster,String action){return monster+"\u0000"+action;}
 public static JSONArray catalog()throws Exception{JSONArray out=new JSONArray();for(JSONObject row:INDEX.values())out.put(new JSONObject(row.toString()));return out;}
 public static JSONObject profile(String monster,String action)throws Exception{JSONObject row=INDEX.get(key(monster,action));if(row==null)return new JSONObject();JSONObject compiled=findCompiled(row);if(!matchesCompiled(row,compiled))return blocked("compiled_save_condition_contract_mismatch");return new JSONObject(row.toString()).put("resolved",true).put("source_blob_sha1",SOURCE_BLOB).put("coverage_status",row.optString("save_ability").isEmpty()||row.optInt("save_dc")<1?"SOURCE_REVIEW_REQUIRED":"BLOCKED_MISSING_CONTEXT").put("condition_applied",false).put("auto_mutation_allowed",false).put("persisted",false);}
 public static JSONObject resolve(JSONObject in){try{
  if(in==null)return blocked("request_required");
  java.util.Set<String> accepted=new java.util.HashSet<>(java.util.Arrays.asList("monster","name","action","source_pointer","source_blob_sha1","save_succeeded","target_eligibility_confirmed","prerequisite_confirmed"));
  java.util.Iterator<String> keys=in.keys();while(keys.hasNext())if(!accepted.contains(keys.next()))return blocked("unrecognized_save_condition_input");
  String monster=in.optString("monster",""),action=in.optString("action","");if(in.has("name")&&!monster.equals(in.optString("name","")))return blocked("cross_monster_input_rejected");
  JSONObject spec=INDEX.get(key(monster,action));if(spec==null)return blocked("unverified_save_condition_profile");
  if(!SOURCE_BLOB.equals(in.optString("source_blob_sha1","")))return blocked("source_blob_pin_mismatch");
  if(!spec.optString("source_pointer").equals(in.optString("source_pointer","")))return blocked("source_pointer_mismatch");
  if(!matchesCompiled(spec,findCompiled(spec)))return blocked("compiled_save_condition_contract_mismatch");
  Object rawSuccess=in.opt("save_succeeded"),rawEligible=in.opt("target_eligibility_confirmed"),rawPrerequisite=in.opt("prerequisite_confirmed");if(!(rawSuccess instanceof Boolean))return blocked("explicit_save_result_required");if(!(rawEligible instanceof Boolean))return blocked("explicit_target_eligibility_required");if(!(rawPrerequisite instanceof Boolean))return blocked("explicit_prerequisite_result_required");
  if(spec.optString("save_ability").isEmpty()||spec.optInt("save_dc")<1)return blocked("source_save_contract_incomplete");
  JSONArray conditions=new JSONArray();boolean apply=Boolean.FALSE.equals(rawSuccess)&&Boolean.TRUE.equals(rawEligible)&&Boolean.TRUE.equals(rawPrerequisite);if(apply)for(String condition:spec.optString("conditions").split(",\\s*"))conditions.put(condition);
  return new JSONObject().put("resolved",true).put("status","condition_proposal_pending_lifecycle_and_host_integration").put("monster",monster).put("action",action).put("source_pointer",spec.optString("source_pointer")).put("source_blob_sha1",SOURCE_BLOB).put("save_succeeded",rawSuccess).put("target_eligibility_confirmed",rawEligible).put("prerequisite_confirmed",rawPrerequisite).put("proposed_conditions",conditions).put("additional_source_effects_manual",true).put("condition_lifecycle_manual",true).put("full_action_resolution",false).put("condition_applied",false).put("persisted",false).put("auto_rolls",false).put("auto_mutation_allowed",false).put("requires_host_commit",true);
 }catch(Exception failure){return blocked("save_condition_resolution_error");}}
